CREATE TYPE "WorldStatus" AS ENUM ('IMPORTING', 'READY');
CREATE TABLE "World" ("id" VARCHAR(128) PRIMARY KEY, "name" VARCHAR(120) NOT NULL, "seed" VARCHAR(256) NOT NULL, "status" "WorldStatus" NOT NULL DEFAULT 'READY', "saveVersion" INTEGER NOT NULL DEFAULT 9, "generatorVersion" INTEGER NOT NULL DEFAULT 1, "revision" INTEGER NOT NULL DEFAULT 0, "incarnationId" VARCHAR(64) NOT NULL UNIQUE, "lastBatchId" VARCHAR(64), "settings" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "lastPlayedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "World_status_lastPlayedAt_idx" ON "World"("status", "lastPlayedAt");
CREATE TABLE "PlayerState" ("worldId" VARCHAR(128) PRIMARY KEY REFERENCES "World"("id") ON DELETE CASCADE, "position" JSONB NOT NULL, "positionVersion" INTEGER NOT NULL DEFAULT 0, "state" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "DimensionState" ("id" BIGSERIAL PRIMARY KEY, "worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "dimension" VARCHAR(64) NOT NULL, "state" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE ("worldId", "dimension"));
CREATE TABLE "ChunkState" ("id" BIGSERIAL PRIMARY KEY, "worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "dimension" VARCHAR(64) NOT NULL, "chunkX" INTEGER NOT NULL, "chunkY" INTEGER NOT NULL, "chunkZ" INTEGER NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, "data" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE ("worldId", "dimension", "chunkX", "chunkY", "chunkZ"));
CREATE INDEX "ChunkState_region_idx" ON "ChunkState"("worldId", "dimension", "chunkX", "chunkZ");
CREATE TABLE "EntityState" ("id" BIGSERIAL PRIMARY KEY, "worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "entityId" VARCHAR(256) NOT NULL, "dimension" VARCHAR(64) NOT NULL, "chunkX" INTEGER NOT NULL, "chunkZ" INTEGER NOT NULL, "generated" BOOLEAN NOT NULL DEFAULT false, "deleted" BOOLEAN NOT NULL DEFAULT false, "state" JSONB, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE ("worldId", "dimension", "entityId"));
CREATE INDEX "EntityState_region_idx" ON "EntityState"("worldId", "dimension", "chunkX", "chunkZ");
CREATE TABLE "ExploredColumn" ("id" BIGSERIAL PRIMARY KEY, "worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "dimension" VARCHAR(64) NOT NULL, "chunkX" INTEGER NOT NULL, "chunkZ" INTEGER NOT NULL, UNIQUE ("worldId", "dimension", "chunkX", "chunkZ"));
CREATE TABLE "DiscoveredBiome" ("id" BIGSERIAL PRIMARY KEY, "worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "dimension" VARCHAR(64) NOT NULL, "biomeId" VARCHAR(128) NOT NULL, UNIQUE ("worldId", "dimension", "biomeId"));
CREATE TABLE "DiscoveredStructure" ("id" BIGSERIAL PRIMARY KEY, "worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "structureId" VARCHAR(256) NOT NULL, "dimension" VARCHAR(64) NOT NULL, "data" JSONB NOT NULL, UNIQUE ("worldId", "structureId"));
CREATE INDEX "DiscoveredStructure_world_dimension_idx" ON "DiscoveredStructure"("worldId", "dimension");
CREATE TABLE "WorldMarker" ("id" VARCHAR(128) NOT NULL, "worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "dimension" VARCHAR(64) NOT NULL, "name" VARCHAR(120) NOT NULL, "color" VARCHAR(16) NOT NULL, "position" JSONB NOT NULL, PRIMARY KEY ("worldId", "id"));
CREATE INDEX "WorldMarker_world_dimension_idx" ON "WorldMarker"("worldId", "dimension");
CREATE TABLE "DataPack" ("namespace" VARCHAR(64) PRIMARY KEY, "source" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "WorldDataPack" ("worldId" VARCHAR(128) NOT NULL REFERENCES "World"("id") ON DELETE CASCADE, "namespace" VARCHAR(64) NOT NULL REFERENCES "DataPack"("namespace") ON DELETE CASCADE, PRIMARY KEY ("worldId", "namespace"));
